$sharedRows = $sharedRows -split '\r?\n'

function Save-Xml([xml]$doc, [string]$path) {
    $settings = New-Object System.Xml.XmlWriterSettings
    $settings.Indent = $true
    $settings.IndentChars = '    '
    $settings.NewLineChars = "`r`n"
    $settings.NewLineHandling = [System.Xml.NewLineHandling]::Replace
    $settings.Encoding = New-Object System.Text.UTF8Encoding($false)
    $writer = [System.Xml.XmlWriter]::Create($path, $settings)
    $doc.Save($writer)
    $writer.Dispose()
}

function Escape-AndroidString([string]$value) {
    $value = $value -replace "\\\\'", "’"
    return $value.Replace("'", "’")
}

function Set-StringValues([string]$path, [string[]]$keys, [string[]]$values, [string]$anchorName) {
    if (-not (Test-Path -LiteralPath $path)) {
        throw "Missing locale file: $path"
    }
    [xml]$doc = Get-Content -LiteralPath $path -Raw
    for ($i = 0; $i -lt $keys.Count; $i++) {
        $key = $keys[$i]
        $value = $values[$i]
        $node = @($doc.resources.string | Where-Object { $_.name -eq $key })[0]
        if ($null -eq $node) {
            $node = $doc.CreateElement('string')
            $node.SetAttribute('name', $key)
            $node.InnerText = Escape-AndroidString $value
            $anchor = @($doc.resources.string | Where-Object { $_.name -eq $anchorName })[0]
            if ($null -ne $anchor) {
                $null = $doc.resources.InsertAfter($node, $anchor)
                $anchorName = $key
            }
            else {
                $null = $doc.resources.AppendChild($node)
            }
        }
        else {
            $node.InnerText = Escape-AndroidString $value
        }
    }
    Save-Xml $doc $path
}

foreach ($row in $voiceRows) {
    if ([string]::IsNullOrWhiteSpace($row)) { continue }
    $parts = $row.Trim() -split '~'
    $locale = $parts[0].Trim()
    $values = $parts[1..($parts.Length - 1)]
    if ($values.Length -ne $voiceKeys.Length) {
        throw \"Voice locale $locale has $($values.Length) values, expected $($voiceKeys.Length)\"
    }
    $path = Join-Path (Get-Location).Path ("biometric-custom-voice\src\main\res\{0}\strings.xml" -f $locale)
    Set-StringValues $path $voiceKeys $values 'biometriccompat_voice_help_timeout'
}

foreach ($row in $sharedRows) {
    if ([string]::IsNullOrWhiteSpace($row)) { continue }
    $parts = $row.Trim() -split '~'
    $locale = $parts[0].Trim()
    $values = $parts[1..($parts.Length - 1)]
    if ($values.Length -ne $sharedKeys.Length) {
        throw \"Shared locale $locale has $($values.Length) values, expected $($sharedKeys.Length)\"
    }
    $path = Join-Path (Get-Location).Path ("biometric\src\main\res\{0}\strings.xml" -f $locale)
    Set-StringValues $path $sharedKeys $values 'biometriccompat_required_crypto_missing_error'
}

Write-Output 'Locale updates applied.'
